package co.kr.badara.dolswevoice;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.location.*;import android.view.*;import android.webkit.*;import android.widget.*;import android.text.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
public final class HomeMapActivity extends Activity implements LocationListener {
 private Config cfg;private WebView map;private EditText radius;private TextView coordinates;private boolean selected,ready;private double lat,lon;private LocationManager locations;private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();private boolean requesting;private final Runnable timeout=()->{stopLocation();notice("위치를 찾지 못했어요. 지도에서 직접 집을 선택해주세요.");};
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(40,83,69));t.setPadding(dp(4),dp(6),dp(4),dp(6));return t;}private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->action.run());return b;}
 public void onCreate(Bundle state){super.onCreate(state);cfg=new Config(this);HomeGate gate=new HomeGate(this,cfg);selected=state!=null?state.getBoolean("selected"):gate.configured();lat=state!=null?state.getDouble("lat"):selected?gate.lat():37.5665;lon=state!=null?state.getDouble("lon"):selected?gate.lon():126.9780;locations=getSystemService(LocationManager.class);
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setFitsSystemWindows(true);root.setPadding(dp(12),dp(8),dp(12),dp(8));root.setBackgroundColor(Color.rgb(246,247,242));setContentView(root);root.addView(text("집 위치와 동작 범위",22));root.addView(text("지도를 누르면 집 위치가 지정됩니다. 범위 안에서만 음성을 듣습니다.",13));
  LinearLayout search=new LinearLayout(this);EditText address=new EditText(this);address.setSingleLine(true);address.setHint("주소 또는 장소 검색");address.setTextSize(14);search.addView(address,new LinearLayout.LayoutParams(0,-2,1));search.addView(button("검색",()->search(address.getText().toString())));root.addView(search);
  map=new WebView(this);map.getSettings().setJavaScriptEnabled(true);map.getSettings().setAllowFileAccess(false);map.getSettings().setAllowContentAccess(false);map.getSettings().setUserAgentString("DolsweVoice/1.1.0 (Android; https://github.com/kojungho/dolswe-voice)");map.addJavascriptInterface(new SelectionBridge(),"HomeSelection");map.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){if(r.isForMainFrame()&&"https".equals(r.getUrl().getScheme())&&"www.openstreetmap.org".equals(r.getUrl().getHost()))try{startActivity(new Intent(Intent.ACTION_VIEW,r.getUrl()));}catch(Exception ignored){}return true;}public void onPageFinished(WebView v,String url){ready=true;}});root.addView(map,new LinearLayout.LayoutParams(-1,0,1));
  coordinates=text("",12);root.addView(coordinates);showCoordinates();root.addView(button("현재 위치로 이동",this::currentLocation));LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(text("집 반경 (m)",15));radius=new EditText(this);radius.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);radius.setSingleLine(true);radius.setText(String.valueOf(state!=null?state.getInt("radius",200):gate.radius()));row.addView(radius,new LinearLayout.LayoutParams(0,-2,1));root.addView(row);radius.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){if(ready)map.evaluateJavascript("setRadius("+radiusValue()+")",null);}public void afterTextChanged(Editable e){}});
  root.addView(text("50~3,000m · 위치 오차를 고려해 200m 이상을 권장합니다. 지도는 OpenStreetMap에 연결합니다.",11));root.addView(button("집 위치와 반경 저장",this::save));
  try{String html="<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><style>html,body,#map{height:100%;margin:0;}"+asset("map/leaflet.css")+"</style></head><body><div id='map'></div><script>"+asset("map/leaflet.js")+"</script><script>var map=L.map('map').setView(["+lat+","+lon+"],16);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);var pin=null,ring=null,radius="+radiusValue()+";function draw(a,b){if(pin)pin.remove();if(ring)ring.remove();pin=L.circleMarker([a,b],{radius:7,color:'#285345',fillOpacity:1}).addTo(map);ring=L.circle([a,b],{radius:radius,color:'#285345',fillOpacity:.12}).addTo(map);}function setHome(a,b){draw(a,b);map.setView([a,b],16);HomeSelection.choose(a,b);}function setRadius(r){radius=r;if(ring)ring.setRadius(r);}map.on('click',function(e){draw(e.latlng.lat,e.latlng.lng);HomeSelection.choose(e.latlng.lat,e.latlng.lng);});"+(selected?"draw("+lat+","+lon+");":"")+"</script></body></html>";map.loadDataWithBaseURL("https://kojungho.github.io/dolswe-voice/",html,"text/html","UTF-8",null);}catch(Exception e){notice("지도 파일을 열 수 없어요.");}
 }
 public final class SelectionBridge {@JavascriptInterface public void choose(double a,double b){runOnUiThread(()->{if(!HomeRegion.valid(a,b,200))return;stopLocation();lat=a;lon=b;selected=true;showCoordinates();});}}
 private String asset(String path)throws Exception{try(InputStream in=getAssets().open(path);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);return out.toString("UTF-8");}}
 private int radiusValue(){try{int n=Integer.parseInt(radius.getText().toString());return Math.max(50,Math.min(3000,n));}catch(Exception e){return 200;}}
 private void showCoordinates(){coordinates.setText(selected?String.format(Locale.US,"집 위치  %.6f, %.6f",lat,lon):"지도에서 집 위치를 선택해주세요");}
 private void save(){int r;try{r=Integer.parseInt(radius.getText().toString());}catch(Exception e){r=0;}if(!selected||!HomeRegion.valid(lat,lon,r)){radius.setBackgroundColor(0xffffe2df);notice("지도에서 집 위치를 선택하고 반경을 50~3,000m로 입력해주세요.");return;}cfg.p.edit().putBoolean("homeSet",true).putLong("homeLat",Double.doubleToLongBits(lat)).putLong("homeLon",Double.doubleToLongBits(lon)).putInt("homeRadius",r).commit();stopService(new Intent(this,VoiceService.class));setResult(RESULT_OK);finish();}
 private void search(String query){if(query.trim().isEmpty())return;if(!ready){notice("지도를 준비하고 있어요. 잠시 후 다시 눌러주세요.");return;}io.execute(()->{try{List<Address> results=new Geocoder(this,Locale.KOREAN).getFromLocationName(query,1);if(results==null||results.isEmpty())throw new Exception("검색 결과가 없어요. 지도에서 직접 선택해주세요.");Address found=results.get(0);runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())map.evaluateJavascript("setHome("+found.getLatitude()+","+found.getLongitude()+")",null);});}catch(Exception e){runOnUiThread(()->notice("주소 검색을 완료하지 못했어요. 지도에서 집 위치를 선택해주세요."));}});}
 private void currentLocation(){if(!ready){notice("지도를 준비하고 있어요. 잠시 후 다시 눌러주세요.");return;}if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},8);return;}try{stopLocation();if(!locations.isLocationEnabled()){notice("휴대폰 위치 기능을 켜주세요.");return;}requesting=true;for(String provider:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER})if(locations.isProviderEnabled(provider))locations.requestLocationUpdates(provider,1000,0,this,Looper.getMainLooper());handler.postDelayed(timeout,20000);}catch(Exception e){stopLocation();notice("위치 권한과 위치 기능을 확인해주세요.");}}
 public void onLocationChanged(Location x){if(!requesting||!x.hasAccuracy()||x.getAccuracy()>500)return;stopLocation();if(ready)map.evaluateJavascript("setHome("+x.getLatitude()+","+x.getLongitude()+")",null);}
 private void stopLocation(){requesting=false;handler.removeCallbacks(timeout);if(locations!=null)try{locations.removeUpdates(this);}catch(Exception ignored){}}
 public void onProviderDisabled(String p){}public void onProviderEnabled(String p){}public void onStatusChanged(String p,int s,Bundle b){}
 public void onRequestPermissionsResult(int request,String[] p,int[] g){super.onRequestPermissionsResult(request,p,g);if(request==8&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)currentLocation();else notice("정확한 위치 권한이 필요합니다. 지도에서는 직접 선택할 수 있어요.");}
 protected void onSaveInstanceState(Bundle b){b.putBoolean("selected",selected);b.putDouble("lat",lat);b.putDouble("lon",lon);b.putInt("radius",radiusValue());super.onSaveInstanceState(b);}
 protected void onDestroy(){stopLocation();io.shutdownNow();if(map!=null){map.removeJavascriptInterface("HomeSelection");map.destroy();}super.onDestroy();}private void notice(String s){if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setMessage(s).setPositiveButton("확인",null).show();}
}
